    case Token.LABEL:
    case Token.LABEL_NAME:
    case Token.SWITCH:
    case Token.BREAK:
    case Token.CATCH:
    case Token.TRY:
    case Token.SCRIPT:
    case Token.EXPR_RESULT:
    case Token.BLOCK:
    case Token.EMPTY:
    case Token.DEFAULT:
    case Token.CONTINUE:
    case Token.DEBUGGER:
    case Token.THROW:
      typeable = false;
      break;

